# 繁中（台灣）→ 简体中文：先換成大陸玩家的卡牌術語，再用 OpenCC 轉簡體字
# 術語對照取自中文化介面的簡體版（_AutoGeneratedTranslations.txt），讓卡片效果和介面用詞一致
import opencc

_cc = opencc.OpenCC('t2s')
# 順序有關係：長的詞要先換（名場面區 在 名場面 之前）
TERMS = [
    ('名場面區', '高潮區'),
    ('名場面', '高潮'),
    ('休息室', '控室'),
    ('傷害區', '時計區'),
    ('牌庫', '卡組'),
]
# 遊戲顯示時會換成圖示的標記，維持原樣（CardText.cs 的 ForDisplay 認這幾個字）
KEEP = ['【名場面連動】']


def to_cn(s):
    for i, k in enumerate(KEEP): s = s.replace(k, '\x00%d\x00' % i)
    for a, b in TERMS: s = s.replace(a, b)
    s = _cc.convert(s)
    for i, k in enumerate(KEEP): s = s.replace('\x00%d\x00' % i, k)
    return s


if __name__ == '__main__':
    for t in ['【自】這張卡放置到你的名場面區時，從你的牌庫抽 1 張卡，將你休息室的 1 張角色放置到傷害區。',
              '【自】【名場面連動】［(1)］這張卡攻擊時，如果「The Magic of Smiles」在你的名場面區，選擇你的 1 張《Music》角色，戰力 +1500。']:
        print(to_cn(t))
